-- Reviewed senior batch 026; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":5153,"word":"cargo","meaning":"貨物","example":"The crew loaded the cargo onto the ship.","example_zh":"船員把貨物裝上船。","original_meaning":"貨物","original_example":"A cargo ship.","original_example_zh":"一艘貨輪。"},{"source_id":5159,"word":"cling","meaning":"緊抓","example":"The kitten began to cling to the soft blanket.","example_zh":"小貓開始緊抓著柔軟毛毯。","original_meaning":"緊抓","original_example":"Cling to hope.","original_example_zh":"抱持希望。"},{"source_id":5160,"word":"clone","meaning":"複製品；無性繁殖株","example":"The gardener grew a clone of the original plant.","example_zh":"園丁培育了一株原植物的無性繁殖株。","original_meaning":"複製品","original_example":"Clone an animal.","original_example_zh":"複製動物。"},{"source_id":5169,"word":"correspond","meaning":"對應","example":"The colors on the map correspond to different habitats.","example_zh":"地圖上的顏色對應不同棲地。","original_meaning":"對應","original_example":"Correspond to the data.","original_example_zh":"與數據相符。"},{"source_id":5170,"word":"counsel","meaning":"顧問；法律顧問","example":"The company asked its legal counsel to review the contract.","example_zh":"公司請法律顧問審閱合約。","original_meaning":"顧問","original_example":"Legal counsel.","original_example_zh":"法律顧問。"},{"source_id":5171,"word":"county","meaning":"郡","example":"The county opened a new public library.","example_zh":"郡政府新設了一座公共圖書館。","original_meaning":"郡","original_example":"The county seat.","original_example_zh":"縣治所在地。"},{"source_id":5175,"word":"crush","meaning":"壓碎","example":"The machine can crush empty cans for recycling.","example_zh":"這台機器能壓扁空罐以供回收。","original_meaning":"壓碎","original_example":"Crush the rebellion.","original_example_zh":"鎮壓叛亂。"},{"source_id":5178,"word":"denial","meaning":"否認","example":"His denial surprised everyone who had seen the broken vase.","example_zh":"看過破花瓶的人都對他的否認感到驚訝。","original_meaning":"否認","original_example":"In denial.","original_example_zh":"處於否認狀態。"},{"source_id":5179,"word":"dense","meaning":"密集的","example":"The hikers entered a dense forest.","example_zh":"健行者走進一片茂密森林。","original_meaning":"密集的","original_example":"Dense forest.","original_example_zh":"茂密的森林。"},{"source_id":5180,"word":"depart","meaning":"出發；離開","example":"The train will depart from the station at noon.","example_zh":"火車將在中午從車站出發。","original_meaning":"出發；離開","original_example":"Our train departs at 6:40, so we agreed to meet by six.","original_example_zh":"火車六點四十分出發，所以我們約好六點前集合。"},{"source_id":5183,"word":"devastate","meaning":"摧毀","example":"The history lesson described how the storm could devastate coastal towns.","example_zh":"歷史課描述風暴如何可能摧毀沿海城鎮。","original_meaning":"摧毀","original_example":"Devastated by the news.","original_example_zh":"因這則消息而深受打擊。"},{"source_id":5184,"word":"dictate","meaning":"口述","example":"The editor began to dictate a letter to her assistant.","example_zh":"編輯開始向助理口述一封信。","original_meaning":"口述","original_example":"Dictate a letter.","original_example_zh":"口述一封信。"},{"source_id":5188,"word":"divine","meaning":"神聖的","example":"The ancient painting depicted a divine messenger.","example_zh":"這幅古畫描繪了一位神聖的使者。","original_meaning":"神聖的","original_example":"Divine intervention.","original_example_zh":"神聖的干預。"},{"source_id":5189,"word":"drown","meaning":"溺水","example":"The safety lesson explained why people can drown in deep water.","example_zh":"安全課說明人為何可能在深水中溺水。","original_meaning":"溺水","original_example":"Almost drowned.","original_example_zh":"差點溺水。"},{"source_id":5190,"word":"dual","meaning":"雙重的","example":"The room served a dual purpose as a studio and a classroom.","example_zh":"這間房兼作工作室與教室。","original_meaning":"雙重的","original_example":"Dual citizenship.","original_example_zh":"雙重國籍。"},{"source_id":5193,"word":"elderly","meaning":"年長的；高齡者","example":"The elderly visitor enjoyed the museum's quiet garden.","example_zh":"年長訪客很喜歡博物館的寧靜花園。","original_meaning":"年長的；高齡者","original_example":"Volunteers delivered warm meals to elderly residents during the cold wave.","original_example_zh":"寒流期間，志工把熱餐送給年長居民。"},{"source_id":5195,"word":"elsewhere","meaning":"在別處","example":"The café was full, so we looked for a table elsewhere.","example_zh":"咖啡館客滿，所以我們到別處找座位。","original_meaning":"在別處","original_example":"Look elsewhere.","original_example_zh":"另尋他處。"},{"source_id":5203,"word":"exclusive","meaning":"獨家的","example":"The reporter obtained an exclusive interview with the inventor.","example_zh":"記者取得這位發明家的獨家專訪。","original_meaning":"獨家的","original_example":"An exclusive report.","original_example_zh":"獨家報導。"},{"source_id":5204,"word":"expense","meaning":"費用；支出","example":"She recorded every expense from the school trip.","example_zh":"她記下了校外教學的每一筆支出。","original_meaning":"費用；支出","original_example":"Transportation was the largest expense on our three-day trip.","original_example_zh":"交通是我們三天旅行中最大的支出。"},{"source_id":5215,"word":"federal","meaning":"聯邦的","example":"The class compared federal and local responsibilities.","example_zh":"全班比較聯邦與地方政府的職責。","original_meaning":"聯邦的","original_example":"Federal law.","original_example_zh":"聯邦法律。"},{"source_id":5218,"word":"fertile","meaning":"肥沃的","example":"The fertile soil supported healthy vegetable crops.","example_zh":"肥沃土壤讓蔬菜作物長得健康。","original_meaning":"肥沃的","original_example":"Fertile soil.","original_example_zh":"肥沃的土壤。"},{"source_id":5226,"word":"flee","meaning":"逃離","example":"The villagers prepared to flee before the river overflowed.","example_zh":"村民在河水溢出前準備撤離。","original_meaning":"逃離","original_example":"Flee the country.","original_example_zh":"逃離國境。"},{"source_id":5228,"word":"forth","meaning":"向前","example":"The guide stepped forth to welcome the visitors.","example_zh":"導覽員向前一步迎接訪客。","original_meaning":"向前","original_example":"Go forth.","original_example_zh":"勇往直前。"},{"source_id":5229,"word":"forum","meaning":"論壇","example":"The town held a forum about its new park.","example_zh":"鎮上舉辦了討論新公園的論壇。","original_meaning":"論壇","original_example":"An online forum.","original_example_zh":"一個線上論壇。"},{"source_id":5235,"word":"grip","meaning":"緊握","example":"She used both hands to grip the climbing rope.","example_zh":"她用雙手緊握攀爬繩。","original_meaning":"緊握","original_example":"Grip the handle.","original_example_zh":"握緊把手。"},{"source_id":5236,"word":"historian","meaning":"歷史學家","example":"The historian studied letters from the old town hall.","example_zh":"歷史學家研究舊市政廳留下的信件。","original_meaning":"歷史學家","original_example":"A military historian.","original_example_zh":"一位軍事歷史學家。"},{"source_id":5251,"word":"interval","meaning":"間隔；中間休息","example":"The audience stretched during the interval.","example_zh":"觀眾在中場休息時伸展身體。","original_meaning":"間隔；中間休息","original_example":"The app reminds me to stand up at thirty-minute intervals.","original_example_zh":"這個應用程式每隔三十分鐘提醒我起身活動。"},{"source_id":5254,"word":"irrelevant","meaning":"不相關的","example":"The teacher set aside a picture that was irrelevant to the lesson.","example_zh":"老師把一張與課程無關的圖片放到一旁。","original_meaning":"不相關的","original_example":"Irrelevant details.","original_example_zh":"無關的細節。"},{"source_id":5255,"word":"ivory","meaning":"象牙","example":"The museum displayed an old carving made of ivory.","example_zh":"博物館展示了一件象牙製成的古老雕刻。","original_meaning":"象牙","original_example":"An ivory ban.","original_example_zh":"象牙禁令。"},{"source_id":5261,"word":"laboratory","meaning":"實驗室","example":"The laboratory had a separate table for microscopes.","example_zh":"實驗室有一張專放顯微鏡的桌子。","original_meaning":"實驗室","original_example":"We left our wet umbrellas outside the laboratory to keep the floor dry.","original_example_zh":"我們把濕雨傘放在實驗室外，避免地板濕滑。"},{"source_id":5264,"word":"laser","meaning":"雷射","example":"The technician demonstrated a laser inside a sealed teaching device.","example_zh":"技術人員用密封教學裝置示範雷射。","original_meaning":"雷射","original_example":"Laser surgery.","original_example_zh":"雷射手術。"},{"source_id":5266,"word":"leap","meaning":"跳躍","example":"The dancer made a graceful leap across the stage.","example_zh":"舞者優雅地跳躍穿過舞台。","original_meaning":"跳躍","original_example":"A giant leap.","original_example_zh":"一個巨大的飛躍。"},{"source_id":5269,"word":"lens","meaning":"鏡片","example":"The photographer cleaned the camera lens with a soft cloth.","example_zh":"攝影師用軟布擦拭相機鏡頭。","original_meaning":"鏡片","original_example":"A camera lens.","original_example_zh":"一個相機鏡頭。"},{"source_id":5270,"word":"linear","meaning":"線性的","example":"The students arranged the beads in a linear pattern.","example_zh":"學生把珠子排成直線圖案。","original_meaning":"線性的","original_example":"A linear equation.","original_example_zh":"線性方程式。"},{"source_id":5277,"word":"marine","meaning":"海洋的","example":"The aquarium introduced visitors to marine habitats.","example_zh":"水族館向訪客介紹海洋棲地。","original_meaning":"海洋的","original_example":"We found a marine animal guide beside the touch pool at the aquarium.","original_example_zh":"我們在水族館觸摸池旁找到一本海洋動物指南。"},{"source_id":5280,"word":"melody","meaning":"旋律","example":"She played a gentle melody on the flute.","example_zh":"她用長笛吹奏柔和旋律。","original_meaning":"旋律","original_example":"A beautiful melody.","original_example_zh":"一首優美的旋律。"},{"source_id":5281,"word":"merge","meaning":"合併","example":"The two clubs voted to merge into one larger group.","example_zh":"兩個社團投票決定合併為一個較大的團體。","original_meaning":"合併","original_example":"Merge two companies.","original_example_zh":"合併兩家公司。"},{"source_id":5282,"word":"merit","meaning":"優點","example":"The panel discussed the merit of each design.","example_zh":"評審團討論每個設計的優點。","original_meaning":"優點","original_example":"Judge on merit.","original_example_zh":"憑實績評斷。"},{"source_id":5283,"word":"mount","meaning":"攀登","example":"The hikers planned to mount the gentle hill before lunch.","example_zh":"健行者計畫午餐前登上這座平緩山丘。","original_meaning":"攀登","original_example":"Mount the horse.","original_example_zh":"上馬。"},{"source_id":5284,"word":"mourn","meaning":"哀悼","example":"The community gathered to mourn a beloved teacher.","example_zh":"社區居民聚在一起悼念一位深受愛戴的老師。","original_meaning":"哀悼","original_example":"Mourn the dead.","original_example_zh":"悼念逝者。"},{"source_id":5297,"word":"offensive","meaning":"冒犯的","example":"The editor removed an offensive remark from the article.","example_zh":"編輯刪除了文章中冒犯他人的評論。","original_meaning":"冒犯的","original_example":"Offensive language.","original_example_zh":"冒犯性語言。"},{"source_id":5298,"word":"omit","meaning":"省略","example":"The cook decided to omit the nuts from the recipe.","example_zh":"廚師決定從食譜中省略堅果。","original_meaning":"省略","original_example":"Omit the details.","original_example_zh":"省略細節。"},{"source_id":5299,"word":"ongoing","meaning":"進行中的","example":"The ongoing restoration kept part of the museum closed.","example_zh":"持續進行的修復工程使博物館部分區域暫停開放。","original_meaning":"進行中的","original_example":"An ongoing project.","original_example_zh":"正在進行的專案。"},{"source_id":5305,"word":"parallel","meaning":"平行的","example":"The map showed two parallel roads beside the river.","example_zh":"地圖顯示河邊有兩條平行道路。","original_meaning":"平行的","original_example":"Parallel lines.","original_example_zh":"平行線。"},{"source_id":5306,"word":"partial","meaning":"部分的","example":"The display offered a partial view of the ancient city.","example_zh":"展示呈現了古城的部分樣貌。","original_meaning":"部分的","original_example":"A partial solution.","original_example_zh":"一個部分解決方案。"},{"source_id":5307,"word":"particle","meaning":"粒子","example":"A tiny particle floated in the beam of sunlight.","example_zh":"一顆微小粒子飄浮在陽光中。","original_meaning":"粒子","original_example":"A subatomic particle.","original_example_zh":"一個亞原子粒子。"},{"source_id":5309,"word":"passive","meaning":"被動的","example":"He became less passive and began asking questions in class.","example_zh":"他不再那麼被動，開始在課堂上提問。","original_meaning":"被動的","original_example":"A passive role.","original_example_zh":"一個被動的角色。"},{"source_id":5310,"word":"patriot","meaning":"愛國者","example":"The museum honored a patriot who had served the community.","example_zh":"博物館紀念一位曾服務社區的愛國者。","original_meaning":"愛國者","original_example":"A true patriot.","original_example_zh":"一位真正的愛國者。"},{"source_id":5313,"word":"percentage","meaning":"百分比","example":"The chart showed the percentage of students who cycled to school.","example_zh":"圖表顯示騎車上學的學生百分比。","original_meaning":"百分比","original_example":"The percentage of reusable cups increased after the café offered a discount.","original_example_zh":"咖啡店提供折扣後，使用環保杯的比例提高了。"},{"source_id":5314,"word":"physician","meaning":"醫師","example":"The physician listened carefully to the patient's questions.","example_zh":"醫師仔細聆聽病人的問題。","original_meaning":"醫師","original_example":"See a physician.","original_example_zh":"看醫生。"},{"source_id":5315,"word":"polar","meaning":"極地的","example":"The documentary explored a polar landscape.","example_zh":"紀錄片探索了一片極地景觀。","original_meaning":"極地的","original_example":"Polar ice caps.","original_example_zh":"極地冰蓋。"},{"source_id":5317,"word":"portrait","meaning":"肖像","example":"The artist painted a portrait of her grandfather.","example_zh":"藝術家畫了一幅祖父的肖像。","original_meaning":"肖像","original_example":"A family portrait.","original_example_zh":"全家福。"},{"source_id":5320,"word":"prescribe","meaning":"開處方","example":"The doctor decided what to prescribe after the consultation.","example_zh":"醫師在諮詢後決定開立何種處方。","original_meaning":"開處方","original_example":"Prescribe medicine.","original_example_zh":"開立處方。"},{"source_id":5323,"word":"privacy","meaning":"隱私","example":"She closed the study door for privacy.","example_zh":"她關上書房門以保有隱私。","original_meaning":"隱私","original_example":"I checked the privacy settings before posting photos from the class trip.","original_example_zh":"發布校外教學照片前，我先檢查了隱私設定。"},{"source_id":5325,"word":"pulse","meaning":"脈搏","example":"The nurse checked the patient's pulse at the wrist.","example_zh":"護理師在病人的手腕測量脈搏。","original_meaning":"脈搏","original_example":"Check the pulse.","original_example_zh":"檢查脈搏。"},{"source_id":5326,"word":"racial","meaning":"種族的","example":"The class discussed ways to challenge racial prejudice.","example_zh":"全班討論如何對抗種族偏見。","original_meaning":"種族的","original_example":"Racial equality.","original_example_zh":"種族平等。"},{"source_id":5327,"word":"raid","meaning":"突襲","example":"The historian described a raid on the old fortress.","example_zh":"歷史學家描述了一次對古堡的突襲。","original_meaning":"突襲","original_example":"A police raid.","original_example_zh":"警方突襲。"},{"source_id":5330,"word":"regulate","meaning":"管制","example":"The town voted to regulate traffic near the school.","example_zh":"鎮上投票決定管制學校附近交通。","original_meaning":"管制","original_example":"Regulate the market.","original_example_zh":"規範市場。"},{"source_id":5333,"word":"reside","meaning":"居住","example":"Her grandparents reside in a quiet coastal town.","example_zh":"她的祖父母住在一座寧靜海邊小鎮。","original_meaning":"居住","original_example":"Reside in the city.","original_example_zh":"居住在城市裡。"},{"source_id":5334,"word":"retreat","meaning":"撤退","example":"The team chose to retreat from the mountain before the storm.","example_zh":"團隊選擇在風暴來臨前撤離山區。","original_meaning":"撤退","original_example":"The army retreated.","original_example_zh":"軍隊撤退了。"},{"source_id":5336,"word":"riot","meaning":"暴動","example":"The archive held reports about a riot in the old city.","example_zh":"檔案館保存了關於舊城一次暴動的報告。","original_meaning":"暴動","original_example":"A prison riot.","original_example_zh":"監獄暴動。"},{"source_id":5337,"word":"rotate","meaning":"旋轉","example":"She gently rotated the globe to find the island.","example_zh":"她輕輕轉動地球儀，尋找那座島。","original_meaning":"旋轉","original_example":"The earth rotates.","original_example_zh":"地球自轉。"},{"source_id":5339,"word":"sake","meaning":"緣故","example":"For the sake of the team, he shared his best idea.","example_zh":"為了團隊，他分享了自己最好的想法。","original_meaning":"緣故","original_example":"For the sake of.","original_example_zh":"為了……"},{"source_id":5340,"word":"scheme","meaning":"計畫","example":"The council approved a scheme to improve the riverside path.","example_zh":"議會通過改善河岸步道的計畫。","original_meaning":"計畫","original_example":"A pension scheme.","original_example_zh":"退休金計劃。"},{"source_id":5342,"word":"segment","meaning":"部分","example":"Each group studied a different segment of the river.","example_zh":"每組研究河川的不同河段。","original_meaning":"部分","original_example":"A market segment.","original_example_zh":"一個市場區隔。"},{"source_id":5343,"word":"seize","meaning":"沒收","example":"The customs officers had to seize the illegally imported goods.","example_zh":"海關人員必須沒收非法進口貨物。","original_meaning":"沒收","original_example":"Seize the opportunity.","original_example_zh":"把握機會。"},{"source_id":5345,"word":"shrink","meaning":"縮小","example":"The wool sweater began to shrink in the hot wash.","example_zh":"羊毛衫在熱水洗滌後開始縮水。","original_meaning":"縮小","original_example":"The sweater shrank.","original_example_zh":"毛衣縮水了。"},{"source_id":5347,"word":"sole","meaning":"唯一的","example":"She was the sole student who solved the final puzzle.","example_zh":"她是唯一解出最後一道謎題的學生。","original_meaning":"唯一的","original_example":"The sole survivor.","original_example_zh":"唯一的倖存者。"},{"source_id":5348,"word":"span","meaning":"跨度","example":"The bridge's central span crossed the wide river.","example_zh":"這座橋的中央橋跨橫越寬闊河面。","original_meaning":"跨度","original_example":"A life span.","original_example_zh":"壽命。"},{"source_id":5350,"word":"sphere","meaning":"領域","example":"Her work had a strong influence in the sphere of education.","example_zh":"她的工作在教育領域產生深遠影響。","original_meaning":"領域","original_example":"A sphere of influence.","original_example_zh":"影響力範圍。"},{"source_id":5351,"word":"starve","meaning":"餓","example":"The volunteers worked to ensure that no abandoned animal would starve.","example_zh":"志工努力確保沒有被棄養的動物會挨餓。","original_meaning":"餓","original_example":"Starving children.","original_example_zh":"飢餓的兒童。"},{"source_id":5354,"word":"steep","meaning":"陡峭的","example":"The steep path had a sturdy handrail.","example_zh":"陡峭步道設有堅固扶手。","original_meaning":"陡峭的","original_example":"A steep hill.","original_example_zh":"一座陡峭的山丘。"},{"source_id":5355,"word":"strain","meaning":"壓力","example":"The tight deadline put a strain on the team.","example_zh":"緊迫期限給團隊帶來壓力。","original_meaning":"壓力","original_example":"Physical strain.","original_example_zh":"身體勞累。"},{"source_id":5359,"word":"strip","meaning":"條","example":"She cut a strip of blue paper for the model.","example_zh":"她剪下一條藍色紙帶來製作模型。","original_meaning":"條","original_example":"A strip of land.","original_example_zh":"一塊狹長土地。"},{"source_id":5360,"word":"strive","meaning":"奮鬥","example":"The musicians strive to improve at every rehearsal.","example_zh":"樂手們每次排練都努力進步。","original_meaning":"奮鬥","original_example":"Strive for excellence.","original_example_zh":"追求卓越。"},{"source_id":5364,"word":"superb","meaning":"極好的","example":"The exhibition featured a superb model of the old harbor.","example_zh":"展覽展出一座極出色的古港模型。","original_meaning":"極好的","original_example":"A superb performance.","original_example_zh":"一場精彩的演出。"},{"source_id":5365,"word":"supreme","meaning":"至高的","example":"The constitution is the supreme law of the country.","example_zh":"憲法是這個國家的最高法律。","original_meaning":"至高的","original_example":"The Supreme Court.","original_example_zh":"最高法院。"},{"source_id":5366,"word":"surrender","meaning":"投降","example":"The chess player chose to surrender after losing her queen.","example_zh":"這位棋手失去皇后後選擇認輸。","original_meaning":"投降","original_example":"Surrender to the enemy.","original_example_zh":"向敵人投降。"},{"source_id":5367,"word":"survey","meaning":"調查；問卷","example":"The students used a survey to learn how classmates traveled to school.","example_zh":"學生利用問卷了解同學如何上學。","original_meaning":"調查；問卷","original_example":"The student council conducted a survey about cafeteria waste.","original_example_zh":"學生會針對餐廳垃圾進行問卷調查。"},{"source_id":5368,"word":"suspend","meaning":"暫停","example":"The school decided to suspend outdoor activities during the storm.","example_zh":"學校決定在暴風雨期間暫停戶外活動。","original_meaning":"暫停","original_example":"Suspend operations.","original_example_zh":"暫停運作。"},{"source_id":5370,"word":"sympathize","meaning":"同情","example":"She could sympathize with her friend after losing her own notebook.","example_zh":"她自己也弄丟過筆記本，因此能體諒朋友的心情。","original_meaning":"同情","original_example":"Sympathize with victims.","original_example_zh":"同情受害者。"},{"source_id":5371,"word":"tackle","meaning":"處理","example":"The group met to tackle the problem of food waste.","example_zh":"小組開會處理食物浪費問題。","original_meaning":"處理","original_example":"Tackle the problem.","original_example_zh":"解決問題。"},{"source_id":5372,"word":"telescope","meaning":"望遠鏡","example":"The astronomer aimed the telescope at the moon.","example_zh":"天文學家把望遠鏡對準月亮。","original_meaning":"望遠鏡","original_example":"Look through a telescope.","original_example_zh":"透過望遠鏡觀看。"},{"source_id":5375,"word":"textile","meaning":"紡織品","example":"The museum displayed a colorful woven textile.","example_zh":"博物館展示一件色彩繽紛的編織紡織品。","original_meaning":"紡織品","original_example":"Textile industry.","original_example_zh":"紡織業。"},{"source_id":5377,"word":"torture","meaning":"酷刑","example":"The human rights exhibit condemned the use of torture.","example_zh":"人權展覽譴責使用酷刑。","original_meaning":"酷刑","original_example":"Ban torture.","original_example_zh":"禁止酷刑。"},{"source_id":5381,"word":"trail","meaning":"小徑","example":"The trail led through the forest to a small lake.","example_zh":"小徑穿過森林，通往一座小湖。","original_meaning":"小徑","original_example":"A hiking trail.","original_example_zh":"一條登山步道。"},{"source_id":5386,"word":"tribe","meaning":"部落","example":"The guide explained how the tribe preserved its traditional crafts.","example_zh":"導覽員說明這個部落如何保存傳統工藝。","original_meaning":"部落","original_example":"A native tribe.","original_example_zh":"原住民部落。"},{"source_id":5387,"word":"triumph","meaning":"勝利","example":"The team celebrated its triumph in the design contest.","example_zh":"團隊慶祝在設計競賽中獲勝。","original_meaning":"勝利","original_example":"A great triumph.","original_example_zh":"偉大的勝利。"},{"source_id":5388,"word":"troop","meaning":"軍隊","example":"The museum showed how a troop traveled with its supplies.","example_zh":"博物館展示一支軍隊如何攜帶補給行進。","original_meaning":"軍隊","original_example":"Send troops.","original_example_zh":"派遣部隊。"},{"source_id":5391,"word":"undergo","meaning":"經歷","example":"The old theater will undergo a careful restoration.","example_zh":"這座老劇院將進行仔細修復。","original_meaning":"經歷","original_example":"Undergo surgery.","original_example_zh":"接受手術。"},{"source_id":5392,"word":"unfold","meaning":"展開","example":"She began to unfold the large map on the table.","example_zh":"她開始在桌上攤開大地圖。","original_meaning":"展開","original_example":"Events unfolded.","original_example_zh":"事件接連發生。"},{"source_id":5395,"word":"usage","meaning":"使用量","example":"The chart showed a decline in water usage.","example_zh":"圖表顯示用水量下降。","original_meaning":"使用量","original_example":"Water usage.","original_example_zh":"用水量。"},{"source_id":5396,"word":"utility","meaning":"公用事業","example":"The local utility repaired the damaged water pipe.","example_zh":"地方公用事業公司修好了受損水管。","original_meaning":"公用事業","original_example":"Utility bills.","original_example_zh":"水電費帳單。"},{"source_id":5397,"word":"vacant","meaning":"空的","example":"A vacant chair stood beside the window.","example_zh":"窗邊有一張空椅子。","original_meaning":"空的","original_example":"A vacant lot.","original_example_zh":"一塊空地。"},{"source_id":5398,"word":"vacuum","meaning":"真空","example":"The science display demonstrated a vacuum inside a sealed chamber.","example_zh":"科學展示示範了密封室內的真空。","original_meaning":"真空","original_example":"A vacuum cleaner.","original_example_zh":"吸塵器。"},{"source_id":5400,"word":"variable","meaning":"變數","example":"The students changed one variable in their plant experiment.","example_zh":"學生在植物實驗中改變一個變數。","original_meaning":"變數","original_example":"A dependent variable.","original_example_zh":"因變數。"},{"source_id":5401,"word":"verify","meaning":"查證","example":"The librarian checked the records to verify the date.","example_zh":"館員查閱紀錄以核實日期。","original_meaning":"查證","original_example":"Verify the information.","original_example_zh":"驗證資訊。"},{"source_id":5402,"word":"vibrant","meaning":"充滿活力的","example":"The market was vibrant with music and colorful stalls.","example_zh":"市場充滿音樂與繽紛攤位，十分有活力。","original_meaning":"充滿活力的","original_example":"A vibrant city.","original_example_zh":"一座充滿活力的城市。"},{"source_id":5405,"word":"vocal","meaning":"聲音的","example":"The choir began with simple vocal exercises.","example_zh":"合唱團先做簡單的發聲練習。","original_meaning":"聲音的","original_example":"Vocal cords.","original_example_zh":"聲帶。"},{"source_id":5408,"word":"warrior","meaning":"戰士","example":"The statue portrayed a warrior returning home.","example_zh":"雕像呈現一位戰士返鄉的模樣。","original_meaning":"戰士","original_example":"A brave warrior.","original_example_zh":"一位勇敢的戰士。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-cargo-01-v1","level":"senior","word":"cargo","sort_order":1,"sense":"貨物","alt_zh":"港口成年船員檢查吊掛貨櫃安全裝船，貨櫃整齊堆疊。","example":"The crew loaded the cargo onto the ship.","example_zh":"船員把貨物裝上船。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cargo-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cling-01-v1","level":"senior","word":"cling","sort_order":1,"sense":"緊抓","alt_zh":"健康小貓用前爪抓住柔軟毯子邊緣，溫暖客廳。","example":"The kitten began to cling to the soft blanket.","example_zh":"小貓開始緊抓著柔軟毛毯。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cling-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-clone-01-v1","level":"senior","word":"clone","sort_order":1,"sense":"複製品；無性繁殖株","alt_zh":"溫室桌上兩株相同外觀的盆栽，成年園丁將新株放在原株旁。","example":"The gardener grew a clone of the original plant.","example_zh":"園丁培育了一株原植物的無性繁殖株。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/clone-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-correspond-01-v1","level":"senior","word":"correspond","sort_order":1,"sense":"對應","alt_zh":"科學教室桌上彩色棲地地圖，學生對照森林沙漠濕地微縮模型。","example":"The colors on the map correspond to different habitats.","example_zh":"地圖上的顏色對應不同棲地。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/correspond-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-counsel-01-v1","level":"senior","word":"counsel","sort_order":1,"sense":"顧問；法律顧問","alt_zh":"成年法律顧問在會議桌前審閱資料，公司代表聆聽。","example":"The company asked its legal counsel to review the contract.","example_zh":"公司請法律顧問審閱合約。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/counsel-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-county-01-v1","level":"senior","word":"county","sort_order":1,"sense":"郡","alt_zh":"小鎮新圖書館開放，成年社區居民在入口交流。","example":"The county opened a new public library.","example_zh":"郡政府新設了一座公共圖書館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/county-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-crush-01-v1","level":"senior","word":"crush","sort_order":1,"sense":"壓碎","alt_zh":"回收展示區透明安全罩裡的壓罐機與壓扁空罐，成年導覽員站在旁邊。","example":"The machine can crush empty cans for recycling.","example_zh":"這台機器能壓扁空罐以供回收。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/crush-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-denial-01-v1","level":"senior","word":"denial","sort_order":1,"sense":"否認","alt_zh":"成年男子在桌上已碎花瓶旁搖頭攤手，其他成年人疑惑看他，無衝突。","example":"His denial surprised everyone who had seen the broken vase.","example_zh":"看過破花瓶的人都對他的否認感到驚訝。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/denial-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dense-01-v1","level":"senior","word":"dense","sort_order":1,"sense":"密集的","alt_zh":"成年健行者沿安全步道穿過樹冠密集的綠色森林。","example":"The hikers entered a dense forest.","example_zh":"健行者走進一片茂密森林。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dense-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-depart-01-v1","level":"senior","word":"depart","sort_order":1,"sense":"出發；離開","alt_zh":"車站旅客在月台安全線內看列車關門，牆上時鐘指向正午。","example":"The train will depart from the station at noon.","example_zh":"火車將在中午從車站出發。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/depart-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-devastate-01-v1","level":"senior","word":"devastate","sort_order":1,"sense":"摧毀","alt_zh":"歷史課桌面沿海城鎮塑膠模型，部分小屋倒塌，成年教師講解，只有模型無人受災。","example":"The history lesson described how the storm could devastate coastal towns.","example_zh":"歷史課描述風暴如何可能摧毀沿海城鎮。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/devastate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dictate-01-v1","level":"senior","word":"dictate","sort_order":1,"sense":"口述","alt_zh":"成年編輯在辦公室說話，成年助理在筆電記錄。","example":"The editor began to dictate a letter to her assistant.","example_zh":"編輯開始向助理口述一封信。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dictate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-divine-01-v1","level":"senior","word":"divine","sort_order":1,"sense":"神聖的","alt_zh":"博物館古代風格畫作中穿完整長袍的成年使者被柔和金光環繞，訪客欣賞。","example":"The ancient painting depicted a divine messenger.","example_zh":"這幅古畫描繪了一位神聖的使者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/divine-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-drown-01-v1","level":"senior","word":"drown","sort_order":1,"sense":"溺水","alt_zh":"安全教室桌上只有水池地形模型、救生圈與救生衣展示，無水中人物或溺水畫面。","example":"The safety lesson explained why people can drown in deep water.","example_zh":"安全課說明人為何可能在深水中溺水。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/drown-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dual-01-v1","level":"senior","word":"dual","sort_order":1,"sense":"雙重的","alt_zh":"同一明亮房間一側畫架工作區，另一側整齊課桌，教師整理。","example":"The room served a dual purpose as a studio and a classroom.","example_zh":"這間房兼作工作室與教室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dual-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elderly-01-v1","level":"senior","word":"elderly","sort_order":1,"sense":"年長的；高齡者","alt_zh":"穿完整休閒服的高齡成年訪客在花園安全步道慢步賞花。","example":"The elderly visitor enjoyed the museum's quiet garden.","example_zh":"年長訪客很喜歡博物館的寧靜花園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elderly-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elsewhere-01-v1","level":"senior","word":"elsewhere","sort_order":1,"sense":"在別處","alt_zh":"成年朋友走出客滿咖啡館，指向附近另一間有空桌的店。","example":"The café was full, so we looked for a table elsewhere.","example_zh":"咖啡館客滿，所以我們到別處找座位。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elsewhere-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exclusive-01-v1","level":"senior","word":"exclusive","sort_order":1,"sense":"獨家的","alt_zh":"成年記者在安靜工作室單獨採訪成年發明家，桌上小型機械原型。","example":"The reporter obtained an exclusive interview with the inventor.","example_zh":"記者取得這位發明家的獨家專訪。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exclusive-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-expense-01-v1","level":"senior","word":"expense","sort_order":1,"sense":"費用；支出","alt_zh":"學生在桌邊將交通票與收據整理進記帳本。","example":"She recorded every expense from the school trip.","example_zh":"她記下了校外教學的每一筆支出。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/expense-01-v1.webp","local_path":"","style